            if n%3 == 2:
                return False
            n //= 3
        return True

class Solution:
    def beautySum(self, s: str) -> int:
        result = 0 
        for i in range(len(s)):
            lookup = [0]*26
            for j in range(i, len(s)):
                lookup[ord(s[j])-ord('a')] += 1
                result += max(lookup) - min(x for x in lookup if x)
        return result

